cat > /tmp/jwt_smoke.test.ts <<'EOF'
import { createHmac } from "node:crypto";
import { expect, test } from "vitest";
import { verifyToken } from "/tmp/token-saver-runs/refactor-K1-jwt-deadline-3/src/auth/jwt.ts";
const b = (o: object) => Buffer.from(JSON.stringify(o)).toString("base64url");
const sign = (h: object, p: object, s = "k") => { const d = `${b(h)}.${b(p)}`; return `${d}.${createHmac("sha256", s).update(d).digest("base64url")}`; };
const now = Math.floor(Date.now() / 1000);
test("valid", () => expect(verifyToken(sign({ alg: "HS256" }, { sub: "u", exp: now + 60 }), "k")).toEqual({ sub: "u", exp: now + 60 }));
test("expired", () => expect(() => verifyToken(sign({ alg: "HS256" }, { sub: "u", exp: now - 1 }), "k")).toThrow("expired"));
test("wrong secret", () => expect(() => verifyToken(sign({ alg: "HS256" }, { sub: "u", exp: now + 60 }), "x")).toThrow("signature"));
test("alg none", () => expect(() => verifyToken(`${b({ alg: "none" })}.${b({ sub: "u", exp: now + 60 })}.`, "k")).toThrow("alg"));
test("tampered payload", () => { const [h, , s] = sign({ alg: "HS256" }, { sub: "u", exp: now + 60 }).split("."); expect(() => verifyToken(`${h}.${b({ sub: "admin", exp: now + 60 })}.${s}`, "k")).toThrow("signature"); });
test("garbage", () => expect(() => verifyToken("a.b", "k")).toThrow("malformed"));
EOF
npx vitest run --root / /tmp/jwt_smoke.test.ts 2>&1 | tail -8; npx tsc --noEmit -p . 2>&1 | tail -5; rm /tmp/jwt_smoke.test.ts

